() => {
  // 检查当前页面上的导出按钮状态和可能的 toast 提示
  const buttons = Array.from(document.querySelectorAll('button')).map(b => b.textContent.trim()).filter(t => t.includes('PDF') || t.includes('渲染') || t.includes('编译'));
  const toasts = Array.from(document.querySelectorAll('[class*="toast"], [class*="Toast"], [role="alert"], [class*="notification"]')).map(e => e.textContent.trim().slice(0, 200));
  return { buttons, toasts };
}

() => {
  window.__pdfErrors = [];
  window.__origConsoleError = console.error;
  console.error = function(...args) {
    const serialized = args.map(a => {
      if (a instanceof Error) return { name: a.name, message: a.message, stack: a.stack ? a.stack.slice(0, 800) : undefined };
      try { return typeof a === 'object' ? JSON.stringify(a).slice(0, 500) : String(a); } catch(e) { return String(a); }
    });
    window.__pdfErrors.push(serialized);
    return window.__origConsoleError.apply(console, args);
  };
  window.addEventListener('error', (e) => {
    window.__pdfErrors.push(['window.onerror', e.message, e.filename, e.lineno]);
  });
  window.addEventListener('unhandledrejection', (e) => {
    const r = e.reason;
    window.__pdfErrors.push(['unhandledrejection', r instanceof Error ? (r.message + ' | ' + (r.stack||'').slice(0,500)) : String(r)]);
  });
  return 'error capture installed';
}

() => new Promise(resolve => setTimeout(async () => {
  const errors = window.__pdfErrors || [];
  const buttons = Array.from(document.querySelectorAll('button')).map(b => b.textContent.trim()).filter(t => t.includes('PDF') || t.includes('渲染') || t.includes('编译'));
  resolve({ errorCount: errors.length, errors: errors.slice(-6), buttons });
}, 10000))

