() => {
  // 监控下载行为：hook createObjectURL 和 anchor click
  window.__downloadTrace = [];
  if (!window.__traceInstalled) {
    window.__traceInstalled = true;
    const origCreateObjectURL = URL.createObjectURL.bind(URL);
    URL.createObjectURL = function(blob) {
      const url = origCreateObjectURL(blob);
      window.__downloadTrace.push({ type: 'createObjectURL', blobType: blob && blob.type, blobSize: blob && blob.size });
      return url;
    };
    const origClick = HTMLAnchorElement.prototype.click;
    HTMLAnchorElement.prototype.click = function() {
      window.__downloadTrace.push({ type: 'anchorClick', download: this.download, href: (this.href || '').slice(0, 80) });
      return origClick.apply(this, arguments);
    };
    // 也捕获成功提示文本
    window.__successObserver = new MutationObserver(() => {
      document.querySelectorAll('*').forEach(el => {
        if (el.children.length === 0 && el.textContent && (el.textContent.includes('导出成功') || el.textContent.includes('成功'))) {
          if (!window.__downloadTrace.some(t => t.type === 'successText' && t.text === el.textContent.trim())) {
            window.__downloadTrace.push({ type: 'successText', text: el.textContent.trim().slice(0, 100) });
          }
        }
      });
    });
    window.__successObserver.observe(document.body, { childList: true, subtree: true });
  }
  return 'trace installed';
}

